def build_constrs (stamp_n : Nat) (condefs : List (conN × List ast_t)) :
    List (conN × Nat × stamp) :=
  MAP (fun cts => (cts.1, LENGTH cts.2, .TypeStamp cts.1 stamp_n)) condefs

