def store_type_extension (tenvS1 tenvS2 : tenv_store) : Prop :=
  ∃ tenvS' : tenv_store, (tenvS2 = FUNION tenvS' tenvS1) ∧
    (∀ l, (FLOOKUP tenvS' l = none) ∨ (FLOOKUP tenvS1 l = none))

def store_type_extension (tenvS1 tenvS2 : tenv_store) : Prop :=
  ∃ tenvS' : tenv_store, (tenvS2 = FUNION tenvS' tenvS1) ∧
    (∀ l, (FLOOKUP tenvS' l = none) ∨ (FLOOKUP tenvS1 l = none))

def interprets0 (mem : U → U → Prop) (γ : tmass U) (name : mlstring) (vs : List mlstring)
    (f : List U → U) : Prop :=
  ∀ τ : tyval U, is_type_valuation0 mem τ → γ name (vs.map τ) = f (vs.map τ)

def interprets0 (mem : U → U → Prop) (γ : tmass U) (name : mlstring) (vs : List mlstring)
    (f : List U → U) : Prop :=
  ∀ τ, is_type_valuation0 mem τ → γ name (MAP τ vs) = f (MAP τ vs)

