def type_ctor (ctMap : ctMap) (_ : Ident modN conN) (ns : Nat × stamp)
    (tti : List tvarN × List Ty × type_ident) : Prop :=
  FLOOKUP ctMap ns.2 = some (tti.1, tti.2.1, tti.2.2) ∧ LENGTH tti.2.1 = ns.1
